// Command loadgen simulates many quiz participants against one or more server
// instances. It doubles as the demo client: it prints a live leaderboard,
// latency percentiles, and a final consistency check comparing the scores the
// server acknowledged to each user against the broadcast leaderboard.
//
// AI-ASSISTED (Claude Code): generated by Claude from a spec of the flags and
// metrics wanted (users spread round-robin across instances, reconnect with
// backoff to the next instance, ack and propagation latency). Verified by
// running it against docker-compose with 1-2 instances, killing an instance
// mid-run to confirm reconnect + score preservation, and checking its
// consistency report and percentiles against the server's /metrics.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"math/rand/v2"
	"os"
	"os/signal"
	"slices"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/coder/websocket"

	"github.com/riorhezaharris/real-time-quiz/internal/protocol"
)

type options struct {
	urls     []string
	quizID   string
	users    int
	ramp     time.Duration
	think    time.Duration
	linger   time.Duration
	duration time.Duration
	report   time.Duration
	prefix   string
}

func main() {
	var o options
	urls := flag.String("urls", "ws://localhost:8081/ws,ws://localhost:8082/ws", "comma-separated server WebSocket URLs; users are spread round-robin")
	flag.StringVar(&o.quizID, "quiz", "demo", "quiz ID to join")
	flag.IntVar(&o.users, "users", 100, "number of simulated users")
	flag.DurationVar(&o.ramp, "ramp", 2*time.Second, "spread user joins over this duration")
	flag.DurationVar(&o.think, "think", 300*time.Millisecond, "mean delay between a user's answers")
	flag.DurationVar(&o.linger, "linger", 2*time.Second, "stay connected this long after answering everything")
	flag.DurationVar(&o.duration, "duration", 2*time.Minute, "hard stop")
	flag.DurationVar(&o.report, "report", 2*time.Second, "progress report interval")
	flag.StringVar(&o.prefix, "prefix", fmt.Sprintf("bot%d", time.Now().Unix()%10000), "user ID prefix (vary it to start fresh)")
	flag.Parse()
	o.urls = strings.Split(*urls, ",")

	ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt)
	defer cancel()
	ctx, cancel = context.WithTimeout(ctx, o.duration)
	defer cancel()

	os.Exit(run(ctx, o))
}

// stats aggregates results from every simulated user.
type stats struct {
	connected, joined, sent, acked, correct, dups, errs, reconnects atomic.Int64

	mu          sync.Mutex
	ackLat      []time.Duration
	propLat     []time.Duration
	latest      protocol.Leaderboard
	finalScores map[string]int64
}

func (s *stats) observeAck(d time.Duration) {
	s.mu.Lock()
	s.ackLat = append(s.ackLat, d)
	s.mu.Unlock()
}

func (s *stats) observeBoard(lb protocol.Leaderboard, prop time.Duration) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if prop > 0 {
		s.propLat = append(s.propLat, prop)
	}
	if lb.ServerTimeMs >= s.latest.ServerTimeMs {
		s.latest = lb
	}
}

func (s *stats) setScore(user string, score int64) {
	s.mu.Lock()
	s.finalScores[user] = score
	s.mu.Unlock()
}

func run(ctx context.Context, o options) int {
	st := &stats{finalScores: map[string]int64{}}
	fmt.Printf("loadgen: %d users → quiz %q on %v\n", o.users, o.quizID, o.urls)

	stopReport := make(chan struct{})
	go func() {
		t := time.NewTicker(o.report)
		defer t.Stop()
		for {
			select {
			case <-stopReport:
				return
			case <-t.C:
				printProgress(st)
			}
		}
	}()

	start := time.Now()
	var wg sync.WaitGroup
	for i := range o.users {
		delay := time.Duration(0)
		if o.users > 1 {
			delay = o.ramp * time.Duration(i) / time.Duration(o.users)
		}
		wg.Add(1)
		go func() {
			defer wg.Done()
			select {
			case <-time.After(delay):
			case <-ctx.Done():
				return
			}
			u := &user{id: fmt.Sprintf("%s-%04d", o.prefix, i), urlIdx: i % len(o.urls), o: o, st: st, answered: map[string]bool{}}
			u.run(ctx)
		}()
	}
	wg.Wait()
	close(stopReport)
	elapsed := time.Since(start)
	return printSummary(st, elapsed)
}

type user struct {
	id       string
	urlIdx   int
	o        options
	st       *stats
	answered map[string]bool
}

// run keeps the user in the quiz until every question is answered,
// reconnecting to the next instance with exponential backoff on failure.
func (u *user) run(ctx context.Context) {
	for attempt := 0; ; attempt++ {
		err := u.session(ctx)
		if err == nil || ctx.Err() != nil {
			return
		}
		u.st.reconnects.Add(1)
		u.urlIdx = (u.urlIdx + 1) % len(u.o.urls)
		backoff := min(100*time.Millisecond<<min(attempt, 5), 3*time.Second)
		backoff += time.Duration(rand.Int64N(int64(backoff/2) + 1)) // jitter
		select {
		case <-time.After(backoff):
		case <-ctx.Done():
			return
		}
	}
}

var errDone = errors.New("done")

func (u *user) session(ctx context.Context) error {
	dialCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
	c, _, err := websocket.Dial(dialCtx, u.o.urls[u.urlIdx], nil)
	cancel()
	if err != nil {
		return err
	}
	c.SetReadLimit(1 << 20)
	defer c.CloseNow()
	u.st.connected.Add(1)
	defer u.st.connected.Add(-1)

	write := func(m protocol.ClientMessage) error {
		b, _ := json.Marshal(m)
		wctx, cancel := context.WithTimeout(ctx, 5*time.Second)
		defer cancel()
		return c.Write(wctx, websocket.MessageText, b)
	}

	joined := make(chan protocol.Joined, 1)
	results := make(chan protocol.AnswerResult, 1)
	readErr := make(chan error, 1)
	var pendingSince atomic.Int64 // unix nanos of first un-propagated correct answer

	go func() {
		for {
			_, data, err := c.Read(ctx)
			if err != nil {
				readErr <- err
				return
			}
			var env struct{ Type string }
			json.Unmarshal(data, &env)
			switch env.Type {
			case protocol.TypeJoined:
				var j protocol.Joined
				json.Unmarshal(data, &j)
				joined <- j
			case protocol.TypeAnswerResult:
				var r protocol.AnswerResult
				json.Unmarshal(data, &r)
				results <- r
			case protocol.TypeLeaderboard:
				var lb protocol.Leaderboard
				json.Unmarshal(data, &lb)
				var prop time.Duration
				if since := pendingSince.Swap(0); since != 0 {
					prop = time.Since(time.Unix(0, since))
				}
				u.st.observeBoard(lb, prop)
			case protocol.TypeError:
				u.st.errs.Add(1)
			}
		}
	}()

	if err := write(protocol.ClientMessage{Type: protocol.TypeJoin, QuizID: u.o.quizID, UserID: u.id, DisplayName: u.id}); err != nil {
		return err
	}
	var j protocol.Joined
	select {
	case j = <-joined:
	case err := <-readErr:
		return err
	case <-time.After(5 * time.Second):
		return errors.New("join timeout")
	}
	u.st.joined.Add(1)
	u.st.setScore(u.id, j.Score)

	for _, q := range j.Questions {
		if u.answered[q.ID] {
			continue // answered before a reconnect
		}
		think := time.Duration(rand.Int64N(int64(2*u.o.think) + 1))
		select {
		case <-time.After(think):
		case <-ctx.Done():
			return ctx.Err()
		case err := <-readErr:
			return err
		}

		sent := time.Now()
		reqID := fmt.Sprintf("%s-%s", u.id, q.ID)
		if err := write(protocol.ClientMessage{Type: protocol.TypeAnswer, RequestID: reqID, QuestionID: q.ID, Answer: q.Options[rand.IntN(len(q.Options))]}); err != nil {
			return err
		}
		u.st.sent.Add(1)
		select {
		case r := <-results:
			u.st.observeAck(time.Since(sent))
			u.st.acked.Add(1)
			u.answered[q.ID] = true
			u.st.setScore(u.id, r.Score)
			if r.AlreadyAnswered {
				u.st.dups.Add(1)
			}
			if r.Correct {
				u.st.correct.Add(1)
				pendingSince.CompareAndSwap(0, sent.UnixNano())
			}
		case err := <-readErr:
			return err
		case <-time.After(5 * time.Second):
			return errors.New("answer timeout")
		}
	}

	// Linger so this user keeps receiving (and measuring) broadcasts.
	select {
	case <-time.After(u.o.linger):
	case <-ctx.Done():
	case err := <-readErr:
		return err
	}
	c.Close(websocket.StatusNormalClosure, "done")
	return nil
}

func printProgress(st *stats) {
	st.mu.Lock()
	lb := st.latest
	st.mu.Unlock()
	fmt.Printf("[progress] connected=%d joined=%d answers=%d/%d correct=%d errors=%d reconnects=%d participants=%d\n",
		st.connected.Load(), st.joined.Load(), st.acked.Load(), st.sent.Load(), st.correct.Load(),
		st.errs.Load(), st.reconnects.Load(), lb.Participants)
	for _, e := range lb.Top[:min(3, len(lb.Top))] {
		fmt.Printf("           #%d %-16s %d\n", e.Rank, e.DisplayName, e.Score)
	}
}

func printSummary(st *stats, elapsed time.Duration) int {
	st.mu.Lock()
	defer st.mu.Unlock()

	fmt.Printf("\n=== summary (%s) ===\n", elapsed.Round(time.Millisecond))
	fmt.Printf("users joined:        %d\n", st.joined.Load())
	fmt.Printf("answers acked:       %d (%.0f/s), correct %d, duplicates %d\n",
		st.acked.Load(), float64(st.acked.Load())/elapsed.Seconds(), st.correct.Load(), st.dups.Load())
	fmt.Printf("errors / reconnects: %d / %d\n", st.errs.Load(), st.reconnects.Load())
	fmt.Printf("answer ack latency:           %s\n", percentiles(st.ackLat))
	fmt.Printf("answer→leaderboard latency:   %s  (includes broadcast throttle)\n", percentiles(st.propLat))

	fmt.Printf("\nfinal leaderboard (v%d, %d participants):\n", st.latest.Version, st.latest.Participants)
	for _, e := range st.latest.Top {
		fmt.Printf("  #%-3d %-18s %d\n", e.Rank, e.DisplayName, e.Score)
	}

	// Consistency: every leaderboard entry for one of our users must match
	// the last score the server acknowledged to that user.
	checked, mismatched := 0, 0
	for _, e := range st.latest.Top {
		if want, ok := st.finalScores[e.UserID]; ok {
			checked++
			if want != e.Score {
				mismatched++
				fmt.Printf("  MISMATCH %s: board=%d acked=%d\n", e.UserID, e.Score, want)
			}
		}
	}
	if mismatched > 0 {
		fmt.Printf("consistency check: FAILED (%d/%d entries)\n", mismatched, checked)
		return 1
	}
	fmt.Printf("consistency check: OK (%d leaderboard entries match acknowledged scores)\n", checked)
	return 0
}

func percentiles(ds []time.Duration) string {
	if len(ds) == 0 {
		return "n/a"
	}
	s := slices.Clone(ds)
	slices.Sort(s)
	p := func(q float64) time.Duration { return s[min(len(s)-1, int(q*float64(len(s))))] }
	return fmt.Sprintf("p50=%s p95=%s p99=%s max=%s (n=%d)",
		p(0.50).Round(10*time.Microsecond), p(0.95).Round(10*time.Microsecond),
		p(0.99).Round(10*time.Microsecond), s[len(s)-1].Round(10*time.Microsecond), len(s))
}
